//go:build arm64

package bitset

// NEON kernels, 64 bools and one word per iteration; they return the words
// converted. Generated by go-asmgen (bitset_arm64_gen.go), in bitset_arm64.s.
func packBoolsKernel(words []uint64, bools []byte) (done int)
func unpackBoolsKernel(words []uint64, bools []byte) (done int)

func packBools(dst []uint64, src []byte) int   { return packBoolsKernel(dst, src) }
func unpackBools(dst []byte, src []uint64) int { return unpackBoolsKernel(src, dst) }
